import {createHash} from 'node:crypto';
import {crc32} from 'node:zlib';
import {planAnswerCollection} from './answer-manifest.mjs';
export const MAX_BUNDLE_BYTES=128*1024*1024;
const limit=MAX_BUNDLE_BYTES;
function zipStored(entries){const parts=[],directory=[];let offset=0;for(const [name,data] of entries){const n=Buffer.from(name,'utf8'),sum=crc32(data),local=Buffer.alloc(30),central=Buffer.alloc(46);local.writeUInt32LE(0x04034b50,0);local.writeUInt16LE(20,4);local.writeUInt16LE(0x800,6);local.writeUInt32LE(sum,14);local.writeUInt32LE(data.length,18);local.writeUInt32LE(data.length,22);local.writeUInt16LE(n.length,26);central.writeUInt32LE(0x02014b50,0);central.writeUInt16LE(20,4);central.writeUInt16LE(20,6);central.writeUInt16LE(0x800,8);central.writeUInt32LE(sum,16);central.writeUInt32LE(data.length,20);central.writeUInt32LE(data.length,24);central.writeUInt16LE(n.length,28);central.writeUInt32LE(offset,42);parts.push(local,n,data);directory.push(central,n);offset+=local.length+n.length+data.length}const d=Buffer.concat(directory),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50,0);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(d.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...parts,d,end])}
export function submissionBundle(files){
 if(!Array.isArray(files)||files.length<2||files.length>20)throw Error('请选择 2 至 20 个文件');
 const first=files[0]?.record;if(!first||typeof first.taskId!=='string'||!first.taskId)throw Error('任务无效');const seen=new Set(),ids=new Set(),entries=[],manifest=[];let total=0;
 for(const item of files){const r=item?.record,data=item?.data;if(!r||r.exam!==first.exam||r.student!==first.student||r.taskId!==first.taskId||typeof r.id!=='string'||!r.id||r.id.length>100||ids.has(r.id)||!Buffer.isBuffer(data)||r.path?.includes('/')||!Number.isSafeInteger(r.size)||r.size!==data.length||createHash('sha256').update(data).digest('hex')!==r.sha256)throw Error('答案身份或文件校验失败');planAnswerCollection({exam:r.exam,student:r.student,device:'candidate-web',available:['candidate-web'],files:[{path:r.path,size:r.size,sha256:r.sha256}]});const key=r.path.normalize('NFKC').toLowerCase();if(seen.has(key))throw Error('文件名重复');seen.add(key);ids.add(r.id);total+=data.length;if(total>limit)throw Error('文件总大小超过限制');const path='files/'+r.path;entries.push([path,data]);manifest.push({id:r.id,name:r.path,size:r.size,sha256:r.sha256})}
 const descriptor=Buffer.from(JSON.stringify({version:1,exam:first.exam,student:first.student,taskId:first.taskId,files:manifest},null,2),'utf8');const result=zipStored([['manifest.json',descriptor],...entries]);if(result.length>limit)throw Error('打包后超过大小限制');return result;
}
